create or replace package body headcount_report as
  function headcount(p_dept_code in varchar2) return number is
    l_count number;
  begin
    select count(*) into l_count from (
        select * from active_staff_v where dept_code = p_dept_code
        union
        select * from permanent_staff where dept_code = p_dept_code
    )
    group by dept_code;
    return l_count;
  end headcount;
end headcount_report;
